-- IDENTITY: the standard surrogate key
CREATE TABLE Customers (
    Id   INT IDENTITY(1,1) PRIMARY KEY,
    Name NVARCHAR(200) NOT NULL
);

-- Explicit insert needs the switch (single session):
SET IDENTITY_INSERT Customers ON;
INSERT INTO Customers (Id, Name) VALUES (500, 'Migrated Co');
SET IDENTITY_INSERT Customers OFF;

-- SEQUENCE: one counter shared by two tables, controlled shape
CREATE SEQUENCE dbo.DocNumber
    AS BIGINT
    START WITH 1000
    INCREMENT BY 1
    MINVALUE 1000
    CACHE 50;

CREATE TABLE Orders (
    OrderId BIGINT PRIMARY KEY DEFAULT (NEXT VALUE FOR dbo.DocNumber),
    OrderDate DATE NOT NULL
);

CREATE TABLE Invoices (
    InvoiceId BIGINT PRIMARY KEY DEFAULT (NEXT VALUE FOR dbo.DocNumber),
    InvoiceDate DATE NOT NULL
);
-- Orders and Invoices share one gap-tolerant number line

-- Procedure-side generation (when the app needs the id before insert):
DECLARE @next BIGINT = NEXT VALUE FOR dbo.DocNumber;
-- ... validate, maybe do other work, then:
-- INSERT INTO Orders (OrderId, OrderDate) VALUES (@next, SYSDATETIME());
-- a failure here leaves a gap — by design

-- Reseed at runtime (IDENTITY needs DBCC; sequence is an object):
-- ALTER SEQUENCE dbo.DocNumber RESTART WITH 1;

-- ❌ Searching for gapless document numbers: both mechanisms skip on rollback/cache
-- ✅ Gapless requires an app-level locked counter table — accept the throughput cost knowingly
